insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_engineer','engineer','noun','a person trained to design, build or repair machines, vehicles or structures','[{"senseId":"engineer_1","meaning":"a person trained to design, build or repair machines, vehicles or structures","acceptedParaphrases":["technical expert","technical specialist"],"masteryContexts":[{"contextId":"u4_11_engineer_meaning","text":"The railway engineer explained how the new bridge could carry heavy freight trains.","meaning":"a person trained to design and build structures","wrongMeanings":["a person trained to drive and park vehicles","a person trained to sell and advertise buildings","a person trained to inspect and sell tickets"]},{"contextId":"u4_11_engineer_paraphrase","text":"The aircraft engineer inspected every engine before the plane was allowed to take off.","meaning":"a person trained to keep machines and systems working","wrongMeanings":["a person trained to fly aircraft and ships","a person trained to guide tourists and visitors","a person trained to sell parts and tools"]}],"situationDistractors":["The pilot welcomed the passengers and announced the flying time.","The guard waved a green flag and the train left the platform.","The tourist asked a stranger for directions to the nearest station.","The taxi driver took the suitcases out of the boot and carried them to the hotel door.","The tourists queued at the ticket office to buy tickets for the afternoon ferry.","The air steward served drinks and then collected the empty cups."],"gapDistractors":[{"contextId":"u4_11_engineer_gap_1","answer":"engineer","wrong":["pilot","passenger","driver"]},{"contextId":"u4_11_engineer_gap_2","answer":"engineer","wrong":["captain","passenger","cook"]},{"contextId":"u4_11_engineer_gap_3","answer":"engineer","wrong":["astronaut","accountant","announcer"]}],"spellingErrors":["enginer","engeneer","enginere","ingineer","enjineer","engineeer"],"masteryPassages":[{"passageId":"u4_11_engineer_passage_1","contextId":"u4_11_engineer_gap_1","text":"The new tunnel was designed with great care. The ____ who planned it spent six years studying how the rock would behave under the river.","answer":"engineer"},{"passageId":"u4_11_engineer_passage_2","contextId":"u4_11_engineer_gap_2","text":"Before every flight, a team checks the aircraft carefully. One ____ inspects the wings, while another tests the electrical system.","answer":"engineer"}],"contextDependentParaphrases":[],"wrongParaphrases":["skilled driver","ticket inspector","safety officer"],"misleadingDistractors":["a person who flies and controls an aircraft","a person who sells vehicles to customers","a person who checks tickets on trains"]}]'::jsonb,'[]'::jsonb,'["railway engineer","qualified engineer","chief engineer"]'::jsonb,'live'),
('vocab_pilot','pilot','noun','a person who flies an aircraft','[{"senseId":"pilot_1","meaning":"a person who flies an aircraft","acceptedParaphrases":["person flying the aeroplane","person at the controls"],"masteryContexts":[{"contextId":"u4_12_pilot_meaning","text":"The pilot landed the aeroplane safely in thick fog.","meaning":"a person who flies an aircraft","wrongMeanings":["a person who builds an aircraft","a person who guides an aircraft from the ground","a person who inspects an aircraft"]},{"contextId":"u4_12_pilot_paraphrase","text":"Our pilot announced that we were flying at ten thousand metres.","meaning":"the person in charge of flying the aeroplane","wrongMeanings":["the person who serves meals on the aeroplane","the person who checks tickets on the aeroplane","the person who carries bags onto the aeroplane"]}],"situationDistractors":["The mechanic changed a flat tyre at the side of the road.","The ticket inspector walked along the train checking everyone’s tickets.","The ferry captain steered the boat slowly into the harbour.","The cyclist stopped beside the road to fix a puncture.","The tourists photographed the old castle from the harbour wall.","The bus driver opened the doors and asked everyone to move to the back."],"gapDistractors":[{"contextId":"u4_12_pilot_gap_1","answer":"pilot","wrong":["mechanic","guard","porter"]},{"contextId":"u4_12_pilot_gap_2","answer":"pilot","wrong":["mechanic","passenger","porter"]},{"contextId":"u4_12_pilot_gap_3","answer":"pilot","wrong":["driver","sailor","cyclist"]}],"spellingErrors":["pilott","pilet","pylot","pilotte","pillot","piolt"],"masteryPassages":[{"passageId":"u4_12_pilot_passage_1","contextId":"u4_12_pilot_gap_1","text":"The aeroplane began its descent through thick cloud. The ____ calmly spoke to the control tower and prepared to land.","answer":"pilot"},{"passageId":"u4_12_pilot_passage_2","contextId":"u4_12_pilot_gap_2","text":"Learning to fly takes years of training and hundreds of hours in the air. Only then can a trainee become a qualified ____ and take passengers on commercial flights.","answer":"pilot"}],"contextDependentParaphrases":[],"wrongParaphrases":["person repairing the aeroplane","person serving on the aeroplane","person travelling on the aeroplane"],"misleadingDistractors":["a person who repairs aircraft engines","a person who serves food on a flight","a person who travels on a flight"]}]'::jsonb,'[]'::jsonb,'["airline pilot","fighter pilot","experienced pilot"]'::jsonb,'live'),
('vocab_airship','airship','noun','a large aircraft filled with gas that is lighter than air, which has engines and can be steered','[{"senseId":"airship_1","meaning":"a large aircraft filled with gas that is lighter than air, which has engines and can be steered","acceptedParaphrases":["gas-filled flying craft","large steerable aircraft"],"masteryContexts":[{"contextId":"u4_13_airship_meaning","text":"In the 1930s, a giant airship carried passengers across the Atlantic in about three days.","meaning":"a large gas-filled aircraft that can be steered","wrongMeanings":["a fast aircraft with wings and jet engines","a large ship that sails across the ocean","a small helicopter with rotating blades"]},{"contextId":"u4_13_airship_paraphrase","text":"The advertising company hired an airship to float above the stadium during the match.","meaning":"a lighter-than-air aircraft with engines","wrongMeanings":["a camera fixed to a tall tower","a helicopter with a long rope","a balloon that drifts with the wind"]}],"situationDistractors":["The helicopter landed on the hospital roof to collect an injured climber.","The hot-air balloon drifted slowly over the fields at sunrise, going wherever the wind took it.","The jet took off at high speed and disappeared into the clouds.","The coach driver stopped at a service area so that the travellers could stretch their legs.","The ferry left the port at noon with two hundred people on board.","A mechanic changed the tyre while the family waited at the roadside."],"gapDistractors":[{"contextId":"u4_13_airship_gap_1","answer":"airship","wrong":["mountain","bridge","tower"]},{"contextId":"u4_13_airship_gap_2","answer":"airship","wrong":["kite","cloud","parachute"]},{"contextId":"u4_13_airship_gap_3","answer":"airship","wrong":["tram","ferry","lorry"]}],"spellingErrors":["airchip","airshp","aireship","airshipp","arship","airsip"],"masteryPassages":[{"passageId":"u4_13_airship_passage_1","contextId":"u4_13_airship_gap_1","text":"Early in the twentieth century, passengers could cross the Atlantic in a huge ____ filled with gas. It moved slowly, but it was quiet and offered a smooth ride.","answer":"airship"},{"passageId":"u4_13_airship_passage_2","contextId":"u4_13_airship_gap_2","text":"A hot-air balloon goes wherever the wind carries it. A powered ____, however, has engines and propellers, so the crew can steer it where they want.","answer":"airship"}],"contextDependentParaphrases":[],"wrongParaphrases":["fast jet aircraft","small rescue helicopter","large passenger ship"],"misleadingDistractors":["a small flying machine with rotating blades","a large bag of hot air that cannot be steered","a fast aircraft with fixed wings and jet engines"]}]'::jsonb,'[]'::jsonb,'["giant airship","passenger airship","airship flight"]'::jsonb,'live'),
('vocab_launch','launch','verb','to send a rocket, ship or aircraft on its way, or to start a new product or service','[{"senseId":"launch_1","meaning":"to send a rocket, ship or aircraft on its way, or to start a new product or service","acceptedParaphrases":["start","introduce"],"masteryContexts":[{"contextId":"u4_14_launch_meaning","text":"The space agency will launch a new satellite from the coast next week.","meaning":"send into the air or space","wrongMeanings":["bring back to Earth","pay for in advance","test on the ground"]},{"contextId":"u4_14_launch_paraphrase","text":"The railway company plans to launch a high-speed service between the two cities.","meaning":"start a new service for the public","wrongMeanings":["close an old service for the public","advertise an old service to the public","increase the price of a service"]}],"situationDistractors":["The company closed the old bus station because too few people used it.","The engineers tested the bridge by driving heavy lorries across it.","The airline cancelled the flight because of thick fog.","The cyclist stopped to pump air into a flat tyre.","The tourists took photographs of the old harbour.","The pilot spoke to the control tower and checked the weather report."],"gapDistractors":[{"contextId":"u4_14_launch_gap_1","answer":"launch","wrong":["cancel","repair","follow"]},{"contextId":"u4_14_launch_gap_2","answer":"launch","wrong":["repair","insure","borrow"]},{"contextId":"u4_14_launch_gap_3","answer":"launch","wrong":["close","copy","sell"]}],"spellingErrors":["lanch","lonch","launche","luanch","launsh","lawnch"],"masteryPassages":[{"passageId":"u4_14_launch_passage_1","contextId":"u4_14_launch_gap_1","text":"The space agency has prepared the rocket for months. If the weather stays calm, it will ____ the satellite from the coast on Friday morning.","answer":"launch"},{"passageId":"u4_14_launch_passage_2","contextId":"u4_14_launch_gap_2","text":"Sales of electric cars have grown quickly in recent years. Several manufacturers plan to ____ new models next year.","answer":"launch"}],"contextDependentParaphrases":[],"wrongParaphrases":["stop","repair","cancel"],"misleadingDistractors":["to stop or cancel something before it begins","to repair something that has been damaged","to move something heavy to a new place"],"grammarForms":{"base":"launch","thirdPerson":"launches","past":"launched","pastParticiple":"launched","ing":"launching"}}]'::jsonb,'[]'::jsonb,'["launch a rocket","launch a service","officially launch"]'::jsonb,'live'),
('vocab_height','height','noun','how tall something is, measured from the bottom to the top','[{"senseId":"height_1","meaning":"how tall something is, measured from the bottom to the top","acceptedParaphrases":["vertical measurement","tallness"],"masteryContexts":[{"contextId":"u4_15_height_meaning","text":"Drivers must check the height of their lorry before they enter a low tunnel.","meaning":"how tall something is from bottom to top","wrongMeanings":["how heavy something is when loaded","how fast something can travel","how much something costs to own"]},{"contextId":"u4_15_height_paraphrase","text":"Engineers measured the height of the new tower before they planned where the lifts would go.","meaning":"the measurement from bottom to top","wrongMeanings":["the measurement from side to side","the measurement from front to back","the measurement of its total weight"]}],"situationDistractors":["The tourists queued at the ticket office to buy tickets for the evening train.","The driver filled the tank with petrol before the long journey.","The ferry carried two hundred cars across the river.","The mechanic checked the oil and replaced a worn tyre.","The guide showed the group a map of the old town and pointed out the museum.","The cyclist waited at the traffic lights for the signal to change."],"gapDistractors":[{"contextId":"u4_15_height_gap_1","answer":"height","wrong":["weight","speed","colour"]},{"contextId":"u4_15_height_gap_2","answer":"height","wrong":["weight","speed","price"]},{"contextId":"u4_15_height_gap_3","answer":"height","wrong":["length","weight","age"]}],"spellingErrors":["hight","heigth","hieght","heighth","heigt","hite"],"masteryPassages":[{"passageId":"u4_15_height_passage_1","contextId":"u4_15_height_gap_1","text":"The lorry driver stopped suddenly before the tunnel. A sign warned that the maximum ____ of vehicles was four metres, and his lorry was taller.","answer":"height"},{"passageId":"u4_15_height_passage_2","contextId":"u4_15_height_gap_2","text":"The new bridge is extremely impressive. Its ____ is more than two hundred metres, so even the tallest ships can pass underneath.","answer":"height"}],"contextDependentParaphrases":[],"wrongParaphrases":["width","weight","distance"],"misleadingDistractors":["how wide something is from side to side","how far one place is from another","how heavy something is when it is lifted"]}]'::jsonb,'[]'::jsonb,'["maximum height","great height","average height"]'::jsonb,'live'),
('vocab_anxious','anxious','adjective','worried or nervous about something that may happen','[{"senseId":"anxious_1","meaning":"worried or nervous about something that may happen","acceptedParaphrases":["worried","nervous"],"masteryContexts":[{"contextId":"u4_16_anxious_meaning","text":"Many passengers feel anxious before their first flight, so the crew explain what each noise means.","meaning":"worried about what may happen","wrongMeanings":["excited about what may happen","angry about what has happened","bored by what is happening"]},{"contextId":"u4_16_anxious_paraphrase","text":"The anxious parents waited at the station, afraid that their daughter’s train had been cancelled.","meaning":"nervous and worried","wrongMeanings":["calm and relaxed","proud and pleased","tired and sleepy"]}],"situationDistractors":["The passengers laughed and chatted happily as the bus rolled along the coast.","The driver whistled a cheerful tune while he waited at the traffic lights.","The young traveller slept peacefully on the night train.","The guide handed out maps and explained the timetable for the day.","The mechanic changed a wheel while the family waited by the road.","The ticket machine at the station accepted only coins."],"gapDistractors":[{"contextId":"u4_16_anxious_gap_1","answer":"anxious","wrong":["bored","proud","sleepy"]},{"contextId":"u4_16_anxious_gap_2","answer":"anxious","wrong":["cheerful","sleepy","generous"]},{"contextId":"u4_16_anxious_gap_3","answer":"anxious","wrong":["pleased","cheerful","sleepy"]}],"spellingErrors":["anxous","anxius","anxcious","ancious","anxiuos","anxsious"],"wordFamilyForms":[{"form":"anxious","partOfSpeech":"adjective","example":"Many first-time flyers feel anxious during take-off.","pedagogicallyUseful":true},{"form":"anxiety","partOfSpeech":"noun","example":"The announcement about the delay caused anxiety among the waiting passengers.","pedagogicallyUseful":true,"altExample":"Her anxiety grew as the departure time came closer and her passport was still missing."},{"form":"anxiously","partOfSpeech":"adverb","example":"The parents waited anxiously at the arrivals gate for their daughter’s flight.","pedagogicallyUseful":true,"altExample":"He checked the departure board anxiously every few minutes."}],"masteryPassages":[{"passageId":"u4_16_anxious_passage_1","contextId":"u4_16_anxious_gap_1","text":"Tom had never travelled by air before. As the aeroplane began to shake in the strong wind, he gripped his seat and felt extremely ____.","answer":"anxious"},{"passageId":"u4_16_anxious_passage_2","contextId":"u4_16_anxious_gap_2","text":"The train was already forty minutes late. Everyone on the platform became ____ about missing their connections, and a queue formed at the information desk.","answer":"anxious"}],"contextDependentParaphrases":[],"wrongParaphrases":["bored","excited","careless"],"misleadingDistractors":["very keen and excited to do something","angry because of a long delay","tired after a long journey"]}]'::jsonb,'["anxiety","anxiously"]'::jsonb,'["feel anxious","extremely anxious","anxious about"]'::jsonb,'live'),
('vocab_vehicle','vehicle','noun','something such as a car, bus or lorry that is used to carry people or goods, especially on land','[{"senseId":"vehicle_1","meaning":"something such as a car, bus or lorry that is used to carry people or goods, especially on land","acceptedParaphrases":["means of transport","form of transport"],"masteryContexts":[{"contextId":"u4_17_vehicle_meaning","text":"The police stopped the vehicle because one of its headlights was broken.","meaning":"something used to carry people or goods on land","wrongMeanings":["a person who drives on public roads","a road used by cars and lorries","a building where cars are kept"]},{"contextId":"u4_17_vehicle_paraphrase","text":"An electric vehicle produces no smoke, so it is better for the air in cities.","meaning":"a machine such as a car or bus used for transport","wrongMeanings":["a station where cars or buses stop","a licence that allows people to drive","a service that sells cars and buses"]}],"situationDistractors":["The tourists walked along the beach and collected shells.","The pilot spoke to the control tower and checked the weather report.","The ticket office closed at six o’clock in the evening.","The family waited on the platform for the late train.","The guide held up a map and pointed at the harbour.","The mountain guide told the climbers to keep close together on the narrow path."],"gapDistractors":[{"contextId":"u4_17_vehicle_gap_1","answer":"vehicle","wrong":["road","garage","bridge"]},{"contextId":"u4_17_vehicle_gap_2","answer":"vehicle","wrong":["road","bridge","garage"]},{"contextId":"u4_17_vehicle_gap_3","answer":"vehicle","wrong":["building","bridge","village"]}],"spellingErrors":["vehical","vehicel","vehicule","veicle","vehicl","vehichle"],"masteryPassages":[{"passageId":"u4_17_vehicle_passage_1","contextId":"u4_17_vehicle_gap_1","text":"The city has banned traffic from the old town. Only an electric ____ with a special permit may enter, and it must travel slowly.","answer":"vehicle"},{"passageId":"u4_17_vehicle_passage_2","contextId":"u4_17_vehicle_gap_2","text":"The police officer waved the driver to the side of the road. The ____ had no lights, and its tyres were worn smooth.","answer":"vehicle"}],"contextDependentParaphrases":[],"wrongParaphrases":["place for parking","type of fuel","kind of road"],"misleadingDistractors":["a wide road with several lanes","a building where cars are repaired","a person who drives a lorry or bus"]}]'::jsonb,'[]'::jsonb,'["electric vehicle","motor vehicle","commercial vehicle"]'::jsonb,'live'),
('vocab_pollution','pollution','noun','damage to air, water or land caused by harmful substances or waste','[{"senseId":"pollution_1","meaning":"damage to air, water or land caused by harmful substances or waste","acceptedParaphrases":["contamination","environmental damage"],"masteryContexts":[{"contextId":"u4_18_pollution_meaning","text":"Traffic fumes are a major cause of air pollution in large cities.","meaning":"damage to the air caused by harmful substances","wrongMeanings":["a shortage of space caused by crowded streets","the noise caused by heavy lorries","the heat caused by sunny weather"]},{"contextId":"u4_18_pollution_paraphrase","text":"The factory was fined because its waste caused serious pollution in the river.","meaning":"harmful damage to water, air or land","wrongMeanings":["a shortage of water or fuel","a rise in the cost of materials","a loss of workers or customers"]}],"situationDistractors":["The sun shone brightly and the beach was clean and empty.","The city council opened a new cycle lane along the river.","The factory workers finished their shift and went home.","The tourists queued at the ticket office to buy tickets for the evening train.","The pilot checked the weather report before take-off.","A cyclist stopped to repair a puncture beside the road."],"gapDistractors":[{"contextId":"u4_18_pollution_gap_1","answer":"pollution","wrong":["travel","supply","conditioning"]},{"contextId":"u4_18_pollution_gap_2","answer":"pollution","wrong":["congestion","accidents","delays"]},{"contextId":"u4_18_pollution_gap_3","answer":"pollution","wrong":["sunshine","silence","friendship"]}],"spellingErrors":["polution","pollushion","pollutian","polluton","pollusion","polutian"],"wordFamilyForms":[{"form":"pollution","partOfSpeech":"noun","example":"Air pollution is a serious problem in many large cities.","pedagogicallyUseful":true},{"form":"pollute","partOfSpeech":"verb","example":"Factories that pollute rivers should be fined heavily.","pedagogicallyUseful":true,"altExample":"Old diesel lorries pollute the air much more than modern electric ones."},{"form":"polluted","partOfSpeech":"adjective","example":"The polluted river smelled terrible and no fish could live in it.","pedagogicallyUseful":true,"altExample":"Cities with polluted air often ask drivers to leave their cars at home."}],"masteryPassages":[{"passageId":"u4_18_pollution_passage_1","contextId":"u4_18_pollution_gap_1","text":"Thousands of cars drive into the city every morning. As a result, the ____ from exhaust fumes makes the air dirty and unpleasant to breathe.","answer":"pollution"},{"passageId":"u4_18_pollution_passage_2","contextId":"u4_18_pollution_gap_2","text":"The factory dumped its waste into the river for years. Fish disappeared, and local people complained about the ____ that had turned the water brown.","answer":"pollution"}],"contextDependentParaphrases":[],"wrongParaphrases":["congestion","overcrowding","deforestation"],"misleadingDistractors":["a shortage of fuel caused by heavy use","a lack of space caused by too many people","a rise in the cost of travelling"]}]'::jsonb,'["pollute","polluted"]'::jsonb,'["air pollution","traffic pollution","reduce pollution"]'::jsonb,'live'),
('vocab_destination','destination','noun','the place to which someone or something is travelling or being sent','[{"senseId":"destination_1","meaning":"the place to which someone or something is travelling or being sent","acceptedParaphrases":["the end of our journey","the place we were heading for"],"masteryContexts":[{"contextId":"u4_19_destination_meaning","text":"Venice is a popular holiday destination for visitors from all over the world.","meaning":"a place that people travel to","wrongMeanings":["a place that people leave from","a road that people drive along","a time that people choose to travel"]},{"contextId":"u4_19_destination_paraphrase","text":"We checked the departure board to confirm the time and the destination of our train.","meaning":"the place the train is going to","wrongMeanings":["the platform the train leaves from","the company that runs the train","the route the train follows"]}],"situationDistractors":["The road ran straight for fifty kilometres before it curved through the hills.","The coach left from the central station at seven o’clock in the morning.","The journey took nearly nine hours because of heavy traffic.","The mechanic checked the oil and filled the tank with petrol.","The ferry captain welcomed everyone on board and pointed out the lifeboats.","The cyclist put on a helmet and fixed a light to the front of the bike."],"gapDistractors":[{"contextId":"u4_19_destination_gap_1","answer":"destination","wrong":["journey","route","departure"]},{"contextId":"u4_19_destination_gap_2","answer":"destination","wrong":["driver","engine","ticket"]},{"contextId":"u4_19_destination_gap_3","answer":"destination","wrong":["route","season","guide"]}],"spellingErrors":["destinashun","destenation","destinasion","destanation","destinaton","distination"],"masteryPassages":[{"passageId":"u4_19_destination_passage_1","contextId":"u4_19_destination_gap_1","text":"We left London at dawn and drove north for most of the day. When we finally reached our ____, a quiet village beside a lake, the sun was already setting.","answer":"destination"},{"passageId":"u4_19_destination_passage_2","contextId":"u4_19_destination_gap_2","text":"The station was busy and several trains were waiting at the platforms. Every train shows its final ____ on the front, so passengers can check they are boarding the right one.","answer":"destination"}],"contextDependentParaphrases":[],"wrongParaphrases":["the start of our journey","the route of our journey","the length of our journey"],"misleadingDistractors":["the road that a journey follows","the place where a journey begins","the time that a journey takes"]}]'::jsonb,'[]'::jsonb,'["final destination","holiday destination","tourist destination"]'::jsonb,'live'),
('vocab_spacious','spacious','adjective','having plenty of room inside','[{"senseId":"spacious_1","meaning":"having plenty of room inside","acceptedParaphrases":["roomy","wide and uncrowded"],"masteryContexts":[{"contextId":"u4_20_spacious_meaning","text":"The new coach is spacious, so passengers can stretch their legs and put large bags at their feet.","meaning":"having plenty of room inside","wrongMeanings":["having very little room for people","having a great many passengers","having a very low price"]},{"contextId":"u4_20_spacious_paraphrase","text":"The spacious departure hall was bright and quiet, with rows of empty seats.","meaning":"large enough to hold many people comfortably","wrongMeanings":["crowded and noisy with queues of people","small and dark with low ceilings","old and dirty with broken equipment"]}],"situationDistractors":["Passengers squeezed together on the bus, holding their bags above their heads.","The tiny cabin had one bed, and the suitcases were stacked in the corridor.","Every seat on the tram was taken, and people were standing in the aisle.","The taxi driver took a shortcut through the old town.","The tourists bought postcards at the kiosk near the harbour.","A cyclist waited at the traffic lights for the green signal."],"gapDistractors":[{"contextId":"u4_20_spacious_gap_1","answer":"spacious","wrong":["crowded","narrow","noisy"]},{"contextId":"u4_20_spacious_gap_2","answer":"spacious","wrong":["crowded","tiny","noisy"]},{"contextId":"u4_20_spacious_gap_3","answer":"spacious","wrong":["tiny","crowded","noisy"]}],"spellingErrors":["spatious","spacius","spaceous","spasious","spacous","spaciuos"],"masteryPassages":[{"passageId":"u4_20_spacious_passage_1","contextId":"u4_20_spacious_gap_1","text":"The old bus was cramped and uncomfortable. By contrast, the new coach is wonderfully ____, with wide seats and plenty of room for luggage.","answer":"spacious"},{"passageId":"u4_20_spacious_passage_2","contextId":"u4_20_spacious_gap_2","text":"The family needed a bigger car for their holiday. They chose a ____ estate car because it could hold four people, two dogs and all their suitcases.","answer":"spacious"}],"contextDependentParaphrases":[],"wrongParaphrases":["cramped","sheltered","decorated"],"misleadingDistractors":["very small and difficult to enter","very crowded with people or things","very clean and carefully organised"]}]'::jsonb,'[]'::jsonb,'["spacious interior","spacious cabin","spacious room"]'::jsonb,'live')
